package Question10;

final class OrderRecord extends Invoice { public OrderRecord(int id, String storeName, String address, String email, String categoryName, String categoryCode, String productName, String productCode, double price, String customerName, String contactNumber, String addressCust, String orderDate, String orderId, String paymentMethod, String paymentStatus, String shippingAddress, double shippingCost){ super(id, storeName, address, email, categoryName, categoryCode, productName, productCode, price, customerName, contactNumber, addressCust, orderDate, orderId, paymentMethod, paymentStatus, shippingAddress, shippingCost); } public double calculateTotalAmount(){ return this.price + this.shippingCost; } }
